const mkMultipart = () => {
  const fd = new FormData()
  fd.append('message', 'hello')
  return new Request('http://localhost/', { method: 'POST', body: fd })
}
const mkUrlencoded = () => {
  const p = new URLSearchParams()
  p.append('message', 'hello')
  return new Request('http://localhost/', { method: 'POST', body: p })
}

const run = async (label: string, fn: () => Promise<unknown>) => {
  try {
    const r = await fn()
    console.log(`[OK]   ${label}:`, JSON.stringify(r))
  } catch (e) {
    console.log(`[FAIL] ${label}:`, (e as Error).message)
  }
}

// Scenario A: c.req.formData() first, then c.req.parseBody() (multipart)
await run('multipart: formData() then parseBody()', async () => {
  const req = new HonoRequest(mkMultipart())
  const fd = await req.formData()
  const parsed = await req.parseBody()
  return { fdMessage: fd.get('message'), parsed }
})

// Scenario B: c.req.formData() first, then c.req.parseBody() (urlencoded)
await run('urlencoded: formData() then parseBody()', async () => {
  const req = new HonoRequest(mkUrlencoded())
  const fd = await req.formData()
  const parsed = await req.parseBody()
  return { fdMessage: fd.get('message'), parsed }
})

// Scenario C: parseBody() then formData()/text()/arrayBuffer()
await run('multipart: parseBody() then formData()/text()', async () => {
  const req = new HonoRequest(mkMultipart())
  const parsed = await req.parseBody()
  const fd = await req.formData()
  const text = await req.text()
  return { parsed, fdMessage: fd.get('message'), textHasOrigBoundary: text.includes(req.header('content-type')!.split('boundary=')[1]) }
})

// Scenario D: parseBody() twice
await run('multipart: parseBody() twice', async () => {
  const req = new HonoRequest(mkMultipart())
  const a = await req.parseBody()
  const b = await req.parseBody()
  return { a, b }
})

// Scenario E: parseBody() then cloneRawRequest and re-parse clone
await run('multipart: parseBody() then cloneRawRequest()', async () => {
  const req = new HonoRequest(mkMultipart())
  const parsed = await req.parseBody()
  const clone = await cloneRawRequest(req)
  const fd = await clone.formData()
  return { parsed, cloneMessage: fd.get('message') }
})

// Scenario F: text() then parseBody() (urlencoded)
await run('urlencoded: text() then parseBody()', async () => {
  const req = new HonoRequest(mkUrlencoded())
  const t = await req.text()
  const parsed = await req.parseBody()
  return { t, parsed }
})

// Scenario G: mixed-case multipart via raw.formData() first (platform handles case?), then parseBody
await run('Multipart/Form-Data: formData() then parseBody()', async () => {
  const src = mkMultipart()
