  const req = new HonoRequest(raw)
  const fd = await req.formData()
  const parsed = await req.parseBody()
  return { fdMessage: fd.get('message'), parsed }
})

// Scenario H: parseBody on plain Request vs HonoRequest for Multipart mixed case where there's an unusual charset param on urlencoded
await run('urlencoded with charset: parseBody()', async () => {
  const p = new URLSearchParams()
  p.append('message', 'hello')
  const raw = new Request('http://localhost/', { method: 'POST', body: p.toString(), headers: { 'content-type': 'Application/X-WWW-Form-Urlencoded; charset=UTF-8' } })
  return parseBody(raw)
})

